# coding: utf-8
from lesson_authoring import entry as E
B=[['古法语 trover／trouver','找到；其更远来源有争议']]
R=B+[['古法语 re- 再 + trover → retrover／retreuver','再次找到'],['中古英语 retreven → 英语 retrieve','找回、取回；后来也指检索信息']]
W=[
E('retrieve','/rɪˈtriːv/','取回；找回；检索','东西放在别处、丢在别处或存进系统，现在把它找出来拿回来。','古法语 re- 再 + trover 找到；联系希腊 trop- 的更远路线只是一种解释。',R,'retrieve your bag 是取回包；retrieve a file 是从存储位置取出文件或数据。原先可以说猎犬找回猎物，后来对象变成记忆或计算机信息，核心仍是找出来、拿回来。','retrieve data；retrieve a file；retrieve information；retrieve something from somewhere。','find 强调找到；retrieve 常多一层取回或调出的动作。把存着的数据读出来，不一定是在修复损坏数据。',('She went back to retrieve the bag she had left behind.','她回去取落下的包。'),('The system retrieves the requested records from the database.','系统从数据库中检索出所需记录。'),sources=['https://www.etymonline.com/word/retrieve','https://www.etymonline.com/word/trove']),
E('retrieval','/rɪˈtriːvəl/','取回；检索','把“去找出并拿回”这整件事当成一个过程。','retrieve + 名词词尾 -al，去掉末尾 e；不是表示形容词的所有 -al 都适用。',R+[['retrieve + -al → retrieval','取回或检索的过程']],'information retrieval 是信息检索：从大量资料中找出相关内容。retrieval of personal belongings 是取回个人物品，词不只用于电脑。','information retrieval；data retrieval；the retrieval of records；a retrieval system。','retrieval 是从已有存储或位置中取得；generation 是产生内容。实际系统可同时做两者，但这两个词指不同动作。',('The archive was redesigned to make document retrieval easier.','档案库经过重新整理，方便检索文件。'),('The team arranged the retrieval of the equipment from the island.','团队安排从岛上取回设备。'),sources=['https://www.etymonline.com/word/retrieval','https://en.wiktionary.org/wiki/retrieval']),
E('retriever','英 /rɪˈtriːvə/；美 /rɪˈtriːvər/','寻回犬；执行检索的人或工具','名字直接来自它的工作：把东西找出来、带回来。','retrieve + -er，表示执行动作的对象；犬种名称由寻回猎物的用途发展。',R+[['retrieve + -er → retriever','取回者 → 寻回犬；检索工具']],'a golden retriever 是金毛寻回犬；技术文章里的 retriever 则可能是检索相关文档的组件。看到工具名称别先联想到狗，仍然抓“找回东西”的功能。','a golden retriever；a Labrador retriever；a document retriever。','retriever 命名行动者或工具，retrieval 命名过程。犬种名称反映历史用途，不是在保证每只狗都经过训练。',('Their golden retriever loves carrying toys back to them.','他们的金毛寻回犬很喜欢把玩具叼回给主人。'),('The document retriever selects passages relevant to the query.','文档检索组件会挑出与查询相关的段落。'),sources=['https://www.etymonline.com/word/retriever','https://en.wiktionary.org/wiki/retriever']),
E('retrievable','/rɪˈtriːvəbl/','可取回的；可检索到的','东西虽然眼下不在手边，但还留有找回来的路径。','retrieve + -able，去掉末尾 e，表示能够被取回。',R+[['retrieve + -able → retrievable','能够被取回或调出的']],'retrievable data 是能够检索或取回的数据。它只说明可取回，不自动保证读取速度快、内容正确，或任何人都有权限访问。','easily retrievable；retrievable data；remain retrievable。','retrievable 说可以取回；available 说可获得或可用。资料存着但暂时没有权限，也不能简单等同于对你 available。',('The records remain retrievable through the archive’s search tool.','这些记录仍可通过档案库的搜索工具检索到。'),('We stored the files in a clearly labelled, easily retrievable format.','我们把文件保存为标签清楚、便于检索的形式。'),sources=['https://www.etymonline.com/word/retrievable','https://en.wiktionary.org/wiki/retrievable']),
E('irretrievable','/ˌɪrɪˈtriːvəbl/','无法取回的；无法挽回的','回去的路已经断了，丢掉的东西或局面无法恢复。','否定 in- 在 r 前同化为 ir-，加 retrievable 可找回的。',R+[['ir- 不 + retrievable → irretrievable','找不回、挽回不了的']],'irretrievable data 指无法取回的数据；an irretrievable loss 则是无法弥补的损失。语气很强，意思不是“目前找起来有点麻烦”。','irretrievable loss；irretrievable damage；irretrievable data。','irretrievable 强调无法取回或挽回；irreversible 强调过程无法逆转。二者可能重叠，但关注点不同。',('The missing letters represented an irretrievable loss to the archive.','那些失踪的信件是档案库无法弥补的损失。'),('Without a surviving copy, the deleted material was irretrievable.','由于没有留存副本，被删除的材料无法找回。')),
E('irretrievably','/ˌɪrɪˈtriːvəbli/','无法挽回地；无可恢复地','结果已经固定下来，想恢复原样也没有办法。','irretrievable 改 -le 为 -ly，形成副词。',R+[['ir- + retrievable → irretrievable','无法挽回的'],['irretrievable → irretrievably','无可挽回地']],'irretrievably lost 是永远丢失；irretrievably damaged 是损害到无法恢复。它强调结果的不可挽回，常搭配 lost、broken、damaged 等。','irretrievably lost；irretrievably damaged；irretrievably broken。','temporarily unavailable 只是暂时不可用；irretrievably lost 已经断言无法找回，不能随便用来描述系统短暂故障。',('Part of the collection was irretrievably lost in the fire.','部分藏品在火灾中永久损失，无法找回。'),('The mistake irretrievably damaged their trust in him.','那个错误无法挽回地损害了他们对他的信任。'))]
